import {prepareActualUI} from './scenes-actual.js';
import {DURATION,chapters,renderFrame} from './film.js';
import {createScore,encodeWav} from './audio.js';
const $=s=>document.querySelector(s),canvas=$('#film'),ctx=canvas.getContext('2d',{alpha:false});
let current=0,playing=false,anchor=0,muted=true,audioContext,scorePromise,score,source,gain,recording=false,recorder,recordChunks=[],recordDestination,recordMime='video/webm',recordError=false;
const fmt=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
let preview=true,starting=false,playRequest=0;
function paint(){renderFrame(ctx,preview?9.8:current);$('#time').value=`${fmt(current)} / 01:36`;$('#timeline').value=current;document.querySelectorAll('.chapter').forEach((e,i)=>{e.classList.toggle('active',Math.floor(Math.min(current,95.99)/12)===i);if(Math.floor(Math.min(current,95.99)/12)===i)e.setAttribute('aria-current','true');else e.removeAttribute('aria-current')});$('#play').textContent=(playing||starting)?'Ⅱ':'▶';$('#play').setAttribute('aria-label',(playing||starting)?'暂停':'播放')}
async function getScore(){if(!scorePromise){$('#status').textContent='正在用振荡器与程序噪声合成配乐…';scorePromise=createScore().then(b=>{score=b;$('#status').textContent='配乐已就绪 · 使用应用真实界面与程序合成音频';return b}).catch(e=>{scorePromise=null;throw e})}return scorePromise}
async function audioReady(){if(!audioContext){audioContext=new AudioContext();gain=audioContext.createGain();gain.connect(audioContext.destination)}await audioContext.resume();return getScore()}
function silence(){if(source){try{source.stop()}catch{}source.disconnect();source=null}}
function syncAudio(){silence();if(!audioContext||!score||!playing)return;gain.gain.value=muted?0:.7;source=audioContext.createBufferSource();source.buffer=score;source.connect(gain);if(recordDestination)source.connect(recordDestination);source.start(0,Math.min(current,DURATION-.001))}
function pause(){playRequest++;starting=false;if(playing)current=Math.min(DURATION,(performance.now()-anchor)/1000);playing=false;silence();paint()}
async function play(withSound=false){const request=++playRequest;starting=true;preview=false;$('#start').hidden=true;if(current>=DURATION-.02)current=0;paint();if(withSound){muted=false;$('#mute').textContent='声音 开';$('#mute').setAttribute('aria-label','关闭声音');try{await audioReady()}catch(e){$('#status').textContent='音频合成失败，可继续静音播放：'+e.message;muted=true;$('#mute').textContent='声音 关';$('#mute').setAttribute('aria-label','开启声音')}}if(request!==playRequest)return;starting=false;anchor=performance.now()-current*1000;playing=true;syncAudio();paint()}
function seek(t){playRequest++;starting=false;preview=false;$('#start').hidden=true;current=Math.max(0,Math.min(DURATION,t));anchor=performance.now()-current*1000;syncAudio();paint()}
function tick(){if(playing){current=Math.min(DURATION,(performance.now()-anchor)/1000);paint();if(recording)$('#record-progress').textContent=`${Math.floor(current/DURATION*100)}%`;if(current>=DURATION){playing=false;silence();if(recording)recorder.stop();paint()}}requestAnimationFrame(tick)}
$('#start').onclick=()=>play(true);$('#play').onclick=()=>(playing||starting)?pause():play(!score);$('#restart').onclick=()=>{seek(0);play()};$('#timeline').oninput=e=>seek(Number(e.target.value));
async function toggleSound(){muted=!muted;if(!muted){try{await audioReady();if(playing){current=Math.min(DURATION,(performance.now()-anchor)/1000);syncAudio()}}catch(e){muted=true;$('#status').textContent=e.message}}if(gain)gain.gain.value=muted?0:.7;$('#mute').textContent=muted?'声音 关':'声音 开';$('#mute').setAttribute('aria-label',muted?'开启声音':'关闭声音')}
$('#mute').onclick=toggleSound;
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.cinema').requestFullscreen()}catch{$('#status').textContent='当前浏览器不支持全屏，请使用浏览器全屏功能。'}}$('#fullscreen').onclick=fullscreen;
chapters.forEach((ch,i)=>{const b=document.createElement('button');b.className='chapter';b.innerHTML=`<span>${String(i+1).padStart(2,'0')} / ${fmt(ch.start)}</span><strong>${ch.name}</strong>`;b.title=ch.description;b.onclick=()=>seek(ch.start+.9);$('.chapters').append(b)});
document.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA/.test(e.target.tagName)||recording)return;if(e.code==='Space'&&/BUTTON|A/.test(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();(playing||starting)?pause():play(!score)}else if(e.code==='ArrowRight'){e.preventDefault();seek(current+5)}else if(e.code==='ArrowLeft'){e.preventDefault();seek(current-5)}else if(e.key.toLowerCase()==='m')toggleSound();else if(e.key.toLowerCase()==='f')fullscreen()});
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
$('#download-audio').onclick=async()=>{const b=$('#download-audio');b.disabled=true;try{download(encodeWav(await getScore()),'dalizi-original-score.wav')}catch(e){$('#status').textContent='导出失败：'+e.message}finally{b.disabled=false}};
function recordUI(on){recording=on;$('.record-status').hidden=!on;document.querySelectorAll('.transport button,.transport input,.chapter,#start,#export,#download-audio').forEach(e=>e.disabled=on)}
$('#export').onclick=async()=>{if(!window.MediaRecorder||!canvas.captureStream){$('#status').textContent='浏览器不支持录制，请使用 Chrome / Edge，或运行项目的离线渲染脚本。';return}pause();$('#export').disabled=true;let captureStream;try{await audioReady();recordDestination=audioContext.createMediaStreamDestination();const video=canvas.captureStream(60);captureStream=video;const stream=new MediaStream([...video.getVideoTracks(),...recordDestination.stream.getAudioTracks()]);recordMime=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'].find(x=>MediaRecorder.isTypeSupported(x));if(!recordMime)throw new Error('当前浏览器没有可用的 WebM 编码器');recorder=new MediaRecorder(stream,{mimeType:recordMime,videoBitsPerSecond:16000000,audioBitsPerSecond:192000});recordChunks=[];recordError=false;recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};recorder.onerror=e=>{recordError=true;$('#status').textContent='录制失败：'+(e.error?.message||'编码器错误')};recorder.onstop=()=>{if(!recordError)download(new Blob(recordChunks,{type:recordMime}),'dalizi-files-film-1080p.webm');stream.getTracks().forEach(t=>t.stop());recordDestination=null;recordUI(false);if(!recordError)$('#status').textContent='WebM 已导出。精确逐帧 MP4 可使用项目的离线渲染脚本生成。'};recordUI(true);seek(0);recorder.start(1000);await play();$('#status').textContent='录制约需 96 秒，请保持页面在前台。可点击下方取消录制。';const cancel=document.createElement('button');cancel.id='cancel-record';cancel.textContent='取消录制';cancel.onclick=()=>{recordError=true;pause();if(recorder.state!=='inactive')recorder.stop();$('#status').textContent='已取消录制。'};$('#status').append(' ',cancel)}catch(e){captureStream?.getTracks().forEach(t=>t.stop());recordDestination?.stream.getTracks().forEach(t=>t.stop());recordUI(false);recordDestination=null;$('#status').textContent='录制失败：'+e.message}};
await prepareActualUI();
window.__film={duration:DURATION,chapters,render:t=>{pause();preview=false;current=t;paint()},renderData:(t,type='image/jpeg',quality=.94)=>{renderFrame(ctx,t);return canvas.toDataURL(type,quality).split(',')[1]},audio:async()=>{const b=encodeWav(await getScore());return Array.from(new Uint8Array(await b.arrayBuffer()))},get state(){return {current,playing,muted,recording}},play,pause,seek};
paint();requestAnimationFrame(tick);
